------------ define ------------

function CatHouseMyCatDialog:__init()
    self.selectIndex = nil ---选择的猫下标
end

function CatHouseMyCatDialog:__delete()
end

function CatHouseMyCatDialog:Awake()
    self:InitData()

end

function CatHouseMyCatDialog:OnFocus(focus)
    focus = checkBool(focus)
    KTool.SetActive(self.controller.gameObject, focus)
    if focus then
        GameUtils.UpdateNavBarShowGoods({ self.goodsId }, true)
    else
        GameUtils.RestoreHealthNodes()
    end
end

function CatHouseMyCatDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:FreshUI()

    end))
    return coWait
end

function CatHouseMyCatDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要

    end))
    return coWait
end

function CatHouseMyCatDialog:InitData()
    -----------------------------
    ---配表相关
    --- 集会中使用货币id
    local goodsId        = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.RallyGoodsId).num)
    self.goodsId         = goodsId
    --- 训练次数上限（同时也是进化所需数量）
    local trainTimeLimit = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.TrainTimeLimit).num)
    self.trainTimeLimit  = trainTimeLimit

    local parameters    = self.controller.Argument.parameters
    self.catList        = parameters.catList
    self.extraParams    = parameters.extraParams
    self.viewType       = parameters.viewType

end

