function CatHouseMyCatDialog:FreshUI()
    self:FreshFilterNode()
    self:SwitchCatSelectShowState()
end

function CatHouseMyCatDialog:FreshFilterNode()
    ---@type UICommonFilterMB
    local nodeEnv = CfUtils.GetLuaScr(self.CommonFilterNode.gameObject, UICommonFilterMBNode)
    if nodeEnv == nil then return end
    nodeEnv:SetFilterClass(Constants.UIFilterType.CatHouse)
    nodeEnv:SetCallback(self.catList, Bind(self, self.OnClickFilterNode), Constants.UISortType.CatHouseFriend)
    nodeEnv:RestoreState("CatHouseMyCatDialog", Bind(self, self.OnClickFilterNode))
end

function CatHouseMyCatDialog:FreshListUI()
    local len  = #self.catList
    local List = self.MyCatList
    if not List.mLoopListView.IsListViewInit then
        List:InitListView(len, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(List, len)
    end
end

function CatHouseMyCatDialog:OnGetItemByIndex(cell, index)
    if index < 0 then
        return nil
    end

    ---@type CatHouseListBtnNode
    local nodeEnv = CfUtils.GetLuaScr(cell, CellEnvPath)
    if isNull(nodeEnv) then
        return nil
    end
    
    local position         = index + 1
    nodeEnv:SetCallback(function (catData)
        self:OnClickCatNodeAction(catData, position)
    end)
    nodeEnv:FreshCommonUI(self.catList[position])
    nodeEnv:FreshCatListUI(false, self.trainTimeLimit)

    return cell

end

---SwitchCatSelectShowState
---刷新猫选择显示状态
function CatHouseMyCatDialog:SwitchCatSelectShowState()
    local isSelect = self.selectIndex ~= nil
    KTool.SetActive(self.NoSelect.gameObject,         not isSelect)
    KTool.SetActive(self.CatHouseTipsNode.gameObject, isSelect)

end

function CatHouseMyCatDialog:RequestRallySignup(catData, price)
    local rallyId = self.extraParams.rallyId
    local playerCatId = catData.id
    GameUtils.Request(Interfaces.CatHouseRallySignup, {
        rallyId = rallyId, playerCatId = playerCatId, price = price
    }, function(req, response)
        ------------------------
        --- 1. 处理数据
        --- 1.1 获取登记持续时间
        local remainTime = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", ConstantsCatHouse.Params.RallySignupSeconds).num)

        --- 1.2 添加登记数据
        ---@type CatHouseComponent
        local component = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatHouseComponent, Constants.CatHouseEntityId)
        component:UpdateRallySignupData(rallyId, {
            rallyId = rallyId, playerCatId = playerCatId,
            price = price, remainTime = remainTime, asked = 0
        })

        --- 1.3 添加登记倒计时数据
        component:UpdateCDData(playerCatId, ConstantsCatHouse.CatStatus.Signup, remainTime)

        ------------------------
        ---2. 回到登记界面
        --if self.callback then
        --    self.callback(self.catData)
        --end
        UIModule.BackDialog()

    end)
end

