function CatHouseMyCatDialog:OnClickFilterNode(dataList, isFilter)
    if isFilter then
        if next(dataList) == nil then
            GameUtils.Toast(localize("当前没有符合要求的猫咪"))
        end
    end

    self.catList = dataList

    self:FreshListUI()

end

function CatHouseMyCatDialog:OnClickCatNodeAction(catData, index)
    ---@type CatHouseTipsNode
    local env = CfUtils.GetLuaScr(self.CatHouseTipsNode, "Game.CatHouse.CatHouseTipsNode")
    if isNull(env) then
        return
    end

    local isSwitchState = self.selectIndex == nil
    self.selectIndex = index
    if isSwitchState then
        self:SwitchCatSelectShowState()
    end

    local viewType    = self.viewType
    local extraParams = self.extraParams
    if viewType == CatListType.Cultivation then
        local geneId = extraParams and checkNumber(extraParams.geneId) or 0
        local isOwnGeneId = geneId > 0
        local extraParams
        if isOwnGeneId then
            extraParams = { geneId = geneId }
        end
        env:FreshUI(catData, viewType, function()
            ---1. 保存cookie
            KCookie.Set(CookieMyCatDataName, catData)
            ---2. 关闭当前界面
            ---因为猫屋主界面常驻 所以 如果想清除记录的话必须移动记录到 UIHomeView
            local moveToRecordId = isOwnGeneId and Constants.UITypeIds.UIHomeView or nil
            CatHouseMgr:GetInstance():BackToMatchPopup(isOwnGeneId, isOwnGeneId, nil, nil, moveToRecordId)
    
        end, extraParams)

    else
        env:FreshUI(catData, viewType, function(_, curPrice)
            ---集会中使用货币id
            local goodsId = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", CatHouseMgr.ConstantsCatHouse.Params.RallyGoodsId).num)
            ---集会手续费（百分比）
            local num     = checkNumber(CfUtils.GetCfVo(AutoIds.IdSetting1903, "BaseArgVo", CatHouseMgr.ConstantsCatHouse.Params.RallySignupHandlingFee).num)
            local numText = string.format("%s%%%%", math.floor(num * 100))
            ---@type GoodsVo
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
            local subText = localize("若被选中配对，收取的_name_需扣除_num_的手续费", {_name_ = goodsVo.name, _num_ = numText})
            GameUtils.SecondConfirm(localize("是否将<color=\"#e71f55\">_name_</color>进行登记", {_name_ = catData.name}), function()
                self:RequestRallySignup(catData, curPrice)

            end, nil, nil, 1, nil, false, subText)
        end) 
    end


end

